# 模拟 Hive 行列转换: LATERAL VIEW explode(数组列) 把一行展开成多行
users = [
    ("u1", ["vip", "new"]),
    ("u2", ["old"]),
    ("u3", ["vip", "active", "new"]),
]

def explode(rows):
    out = []
    for uid, tags in rows:
        for t in tags:
            out.append((uid, t))
    return out

print("原始表(user_id, tags[]):")
for uid, tags in users:
    print(f"  {uid}\t{tags}")
expanded = explode(users)
print(f"\nLATERAL VIEW explode(tags) 后 -> {len(expanded)} 行(一行一标签):")
for uid, t in expanded:
    print(f"  {uid}\t{t}")
print("\n用途: 统计各标签人数、把 JSON/数组字段摊平成可聚合的关系表; 反向用 collect_list 做行转列")
